const express = require('express');
const router = express.Router();
const db = require('../db');

router.post('/complimentary', (req, res) => {
    // Retrieve the user's role from the database
    db.query('SELECT role FROM Employee WHERE id = ?', [req.headers.userid], (err, result) => {
        if (err) {
            console.log(err);
            return res.status(500).json({ message: 'Error retrieving user role.' });
        }
        if (result.length === 0) {
            return res.status(404).json({ message: 'User not found.' });
        }

        const userRole = result[0].role;

        // Retrieve the role's permissions
        db.query('SELECT permissions FROM Roles WHERE name = ?', [userRole], (err, result) => {
            if (err) {
                console.log(err);
                return res.status(500).json({ message: 'Error retrieving role permissions.' });
            }

            if (result.length === 0) {
                return res.status(404).json({ message: 'Role not found.' });
            }

            const permissions = result[0].permissions;

            // Check if the role has the permission to add complimentary leaves
            if (!permissions.includes('add_complimentary')) {
                return res.status(401).json({ message: 'Unauthorized. Your role does not have the permission to add complimentary leaves.' });
            }

            // Retrieve the complimentary leave information from the request body
            const { employeeId, startDate, endDate, reason } = req.body;

            // Validate required fields
            if (!employeeId || !startDate || !endDate || !reason) {
                return res.status(400).json({ message: 'Missing required fields: employeeId, startDate, endDate, reason' });
            }

            // Validate date format and ensure startDate is before endDate
            const startDateObj = new Date(startDate);
            const endDateObj = new Date(endDate);

            if (isNaN(startDateObj.getTime()) || isNaN(endDateObj.getTime())) {
                return res.status(400).json({ message: 'Invalid date format.' });
            }

            if (startDateObj >= endDateObj) {
                return res.status(400).json({ message: 'Start date must be before end date.' });
            }

            // Insert the complimentary leave information into the database
            db.query('INSERT INTO ComplimentaryLeaves (employeeId, startDate, endDate, reason, createdDate, status) VALUES (?, ?, ?, ?, NOW(), "pending")', 
                [employeeId, startDate, endDate, reason], (err, result) => {
                if (err) {
                    console.log(err);
                    return res.status(500).json({ message: 'Error adding complimentary leave.' });
                }

                // Return success response
                return res.status(201).json({
                    message: 'Complimentary leave successfully added.',
                    leaveId: result.insertId
                });
            });
        });
    });
});

